<template>
  <q-page class="customer-flow-page"><div class="page-heading"><div><div class="eyebrow">MORE CONTROL, EVERY DAY</div><h1 class="page-title">My cards</h1><p class="page-subtitle">Virtual cards for your Bembank accounts. These cards cannot make payments.</p></div><q-btn color="primary" icon="add" label="Create card" @click="createOpen = true" :disable="!availableAccounts.length" /></div><q-banner v-if="error" class="bg-red-1 text-red-9 q-mb-md">{{ error }}<q-btn flat label="Retry" @click="load" /></q-banner><q-linear-progress v-if="loading" indeterminate />
    <div class="customer-account-grid"><section v-for="card in cards" :key="card.id" class="customer-panel"><div class="virtual-card" :class="{ 'card-muted': card.status !== 'ACTIVE' }"><div class="row items-center justify-between"><span class="row items-center"><BankLogo style="width:28px;margin-right:8px" /> BEMBANK</span><small>VIRTUAL</small></div><q-icon name="memory" size="36px" class="q-mt-lg" /><div class="card-number">•••• &nbsp; •••• &nbsp; •••• &nbsp; {{ card.last_four }}</div><div class="row justify-between"><span>{{ auth.fullName || auth.username }}</span><span>{{ card.status }}</span></div></div><q-list separator class="q-mt-md"><q-item clickable @click="selected = card; detailsOpen = true"><q-item-section avatar><q-icon name="credit_card" /></q-item-section><q-item-section>Card details</q-item-section><q-item-section side><q-icon name="chevron_right" /></q-item-section></q-item><q-item><q-item-section><q-item-label>Freeze card</q-item-label><q-item-label caption>Pause this card</q-item-label></q-item-section><q-item-section side><q-toggle :model-value="card.status === 'FROZEN'" :disable="busy || card.status === 'LOST'" aria-label="Freeze card" @update:model-value="v => update(card, { status: v ? 'FROZEN' : 'ACTIVE' })" /></q-item-section></q-item><q-item clickable :disable="card.status === 'LOST' || busy" @click="changeLimit(card)"><q-item-section avatar><q-icon name="tune" /></q-item-section><q-item-section>Spending limit</q-item-section><q-item-section side>₱ {{ Number(card.spending_limit).toLocaleString('en-PH') }}</q-item-section></q-item><q-item clickable :disable="card.status === 'LOST' || busy" @click="selected = card; pinOpen = true"><q-item-section avatar><q-icon name="password" /></q-item-section><q-item-section>{{ card.pin_set ? 'Change PIN' : 'Set PIN' }}</q-item-section><q-item-section side><q-icon name="chevron_right" /></q-item-section></q-item><q-item clickable :disable="card.status === 'LOST' || busy" @click="reportLost(card)"><q-item-section avatar><q-icon name="report_gmailerrorred" color="negative" /></q-item-section><q-item-section class="text-negative">Report lost card</q-item-section></q-item></q-list></section></div>
    <div v-if="!loading && !cards.length" class="empty-state"><q-icon name="credit_card" size="50px" /><h2>Your card, your control</h2><p>Create a card for an active account to explore card controls.</p></div>
    <q-dialog v-model="createOpen"><q-card style="width:420px"><q-form @submit="create"><q-card-section><h2 class="section-heading">Create a virtual card</h2><q-select v-model="accountId" :options="availableAccounts" emit-value map-options filled label="Choose an account" :rules="[v => !!v || 'Choose an account']" /></q-card-section><q-card-actions align="right"><q-btn flat label="Cancel" v-close-popup /><q-btn color="primary" label="Create card" type="submit" :loading="busy" /></q-card-actions></q-form></q-card></q-dialog>
    <q-dialog v-model="pinOpen" @hide="pin = ''; password = ''"><q-card style="width:420px"><q-form @submit="savePin"><q-card-section class="q-gutter-md"><h2 class="section-heading">Set your six-digit PIN</h2><q-input v-model="password" type="password" autocomplete="current-password" filled label="Current password" :rules="[v => !!v || 'Required']" /><q-input v-model="pin" type="password" inputmode="numeric" maxlength="6" filled label="New six-digit PIN" :rules="[v => /^[0-9]{6}$/.test(v) || 'Enter exactly six digits']" /><p class="page-subtitle">Your PIN is stored as a hash. Cards are not connected to a payment network.</p></q-card-section><q-card-actions align="right"><q-btn flat label="Cancel" v-close-popup /><q-btn color="primary" label="Save PIN" type="submit" :loading="busy" /></q-card-actions></q-form></q-card></q-dialog>
    <q-dialog v-model="detailsOpen"><q-card style="width:440px;max-width:95vw"><q-card-section v-if="selected"><h2 class="section-heading">Card details</h2><q-list separator><q-item><q-item-section><q-item-label caption>Cardholder</q-item-label><q-item-label>{{ auth.fullName || auth.username }}</q-item-label></q-item-section></q-item><q-item><q-item-section><q-item-label caption>Linked account</q-item-label><q-item-label>{{ accounts.find(a => a.id === selected.account_id)?.account_number }}</q-item-label></q-item-section></q-item><q-item><q-item-section><q-item-label caption>Card ending</q-item-label><q-item-label>•••• {{ selected.last_four }}</q-item-label></q-item-section></q-item><q-item><q-item-section><q-item-label caption>Status</q-item-label><q-item-label>{{ selected.status }}</q-item-label></q-item-section></q-item><q-item><q-item-section><q-item-label caption>Spending limit</q-item-label><q-item-label>PHP {{ Number(selected.spending_limit).toLocaleString('en-PH', {minimumFractionDigits:2}) }}</q-item-label></q-item-section></q-item><q-item><q-item-section><q-item-label caption>PIN</q-item-label><q-item-label>{{ selected.pin_set ? 'Set' : 'Not set' }}</q-item-label></q-item-section></q-item></q-list><p class="page-subtitle q-mt-md">This virtual card is for classroom banking. It has no payment-network card number or CVV.</p></q-card-section><q-card-actions align="right"><q-btn flat label="Close" v-close-popup /></q-card-actions></q-card></q-dialog>
  </q-page>
</template>
<script setup>
import { ref, computed, onMounted } from 'vue'
import { useQuasar } from 'quasar'
import { useAuthStore } from '@/stores/auth-store'
import BankLogo from '@/components/BankLogo.vue'
import api from '@/services/api'
const auth = useAuthStore(), $q = useQuasar(), cards = ref([]), accounts = ref([]), loading = ref(false), busy = ref(false), error = ref(''), createOpen = ref(false), pinOpen = ref(false), detailsOpen = ref(false), selected = ref(null), pin = ref(''), password = ref(''), accountId = ref(null)
const availableAccounts = computed(() => accounts.value.filter(a => a.status === 'ACTIVE' && !cards.value.some(c => c.account_id === a.id)).map(a => ({ label: a.account_number, value: a.id })))
const fail = e => $q.notify({ type: 'negative', message: typeof e.response?.data?.detail === 'string' ? e.response.data.detail : 'Could not update the card. Please retry.' })
async function load () { loading.value = true; error.value = ''; try { const [c, a] = await Promise.all([api.get('/customer/cards/'), api.get('/customer/accounts/')]); cards.value = c.data; accounts.value = a.data } catch { error.value = 'Could not load cards.' } finally { loading.value = false } }
async function create () { busy.value = true; try { await api.post('/customer/cards/', { account_id: accountId.value }); createOpen.value = false; accountId.value = null; await load() } catch (e) { fail(e) } finally { busy.value = false } }
async function update (card, changes) { busy.value = true; try { await api.put(`/customer/cards/${card.id}`, { status: card.status, spending_limit: card.spending_limit, ...changes }); await load() } catch (e) { fail(e) } finally { busy.value = false } }
function changeLimit (card) { $q.dialog({ title: 'Spending limit (PHP)', prompt: { model: String(card.spending_limit), type: 'number', isValid: v => Number(v) > 0 }, cancel: true }).onOk(v => update(card, { spending_limit: v })) }
function reportLost (card) { $q.dialog({ title: 'Report this card as lost?', message: 'The card will be permanently blocked and cannot be reactivated.', cancel: true }).onOk(() => update(card, { status: 'LOST' })) }
async function savePin () { busy.value = true; try { await api.post(`/customer/cards/${selected.value.id}/pin`, { pin: pin.value, password: password.value }); pinOpen.value = false; await load(); $q.notify({ type: 'positive', message: 'PIN updated' }) } catch (e) { fail(e) } finally { busy.value = false } }
onMounted(load)
</script>
